    function run(uint amount) public payable {
        require(true);
        uint balBefore = address(c).balance;
        uint countBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
